const canvasShapesPlugin = {
  id: "canvasShapesPlugin",
  afterDraw(chart, args, pluginOptions) {
    if (!pluginOptions || !Array.isArray(pluginOptions.shapes)) return;
    const { ctx, scales } = chart;
    const xScale = scales.x;
    const yScale = scales.y;
    const x = (value) => xScale.getPixelForValue(value);
    const y = (value) => yScale.getPixelForValue(value);
    const dx = (value) => Math.abs(x(value) - x(0));
    function style(shape) {
      ctx.lineWidth = shape.lineWidth ?? 1.5;
      ctx.strokeStyle = shape.stroke ?? "#000000";
      ctx.fillStyle = shape.fill ?? "rgba(0,0,0,0)";
      ctx.font = shape.font ?? "13px Arial";
      ctx.textAlign = shape.textAlign ?? "center";
      ctx.textBaseline = shape.textBaseline ?? "middle";
    }
    ctx.save();
    for (const shape of pluginOptions.shapes) {
      style(shape);
      if (shape.type === "text") { ctx.fillStyle = shape.fill ?? "#000000"; ctx.fillText(shape.text, x(shape.x), y(shape.y)); }
      if (shape.type === "rectangle") {
        const left = x(shape.x), top = y(shape.y + shape.height), width = x(shape.x + shape.width) - x(shape.x), height = y(shape.y) - y(shape.y + shape.height);
        ctx.beginPath(); ctx.rect(left, top, width, height); if (shape.fill && shape.fill !== "transparent") ctx.fill(); ctx.stroke();
      }
      if (shape.type === "line") { ctx.beginPath(); ctx.moveTo(x(shape.x1), y(shape.y1)); ctx.lineTo(x(shape.x2), y(shape.y2)); ctx.stroke(); }
      if (shape.type === "polygon") { ctx.beginPath(); shape.points.forEach((p,i)=>{ const px=x(p[0]), py=y(p[1]); if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py); }); ctx.closePath(); if(shape.fill && shape.fill !== "transparent") ctx.fill(); ctx.stroke(); }
      if (shape.type === "circle") { ctx.beginPath(); ctx.arc(x(shape.x), y(shape.y), dx(shape.r), 0, Math.PI*2); if(shape.fill && shape.fill !== "transparent") ctx.fill(); ctx.stroke(); }
      if (shape.type === "arc") { ctx.beginPath(); ctx.arc(x(shape.x), y(shape.y), dx(shape.r), shape.startAngle ?? 0, shape.endAngle ?? Math.PI*2, shape.anticlockwise ?? false); if(shape.closePath){ctx.lineTo(x(shape.x), y(shape.y)); ctx.closePath();} if(shape.fill && shape.fill !== "transparent") ctx.fill(); ctx.stroke(); }
    }
    ctx.restore();
  }
};
